"""CPU-only synthetic contract demonstration, NOT a capacity benchmark.

Run from repository root: python extensions/online_admission/replay.py
Prints JSONL to stdout; never connects to a GPU or a live gateway.
"""
from dataclasses import asdict
import json

from feedback import ClassEvidence, Feedback, Window


def demonstrate():
    controller = Feedback(['short'])
    # These pressures are scripted evidence, not generated by a queueing model.
    scenarios = [
        (0, .5, 'healthy'), (10, .5, 'healthy'),
        (20, .5, 'settling'), (30, .5, 'settling'),
        (40, 1.2, 'overload'),
        (50, .5, 'settling'), (60, .5, 'settling'),
        (70, .5, 'recovery'), (80, .5, 'actuator_failure'),
        (90, .5, 'settling'), (100, .5, 'settling'),
        (110, .5, 'recovery'), (120, .5, 'recovery'),
    ]
    records = []
    for start, pressure, scenario in scenarios:
        before = controller.rate
        revision = controller.revision
        evidence = ClassEvidence(40, 0, pressure, pressure)
        decision = controller.observe(Window(start, start + 10, revision, 20, {'short': evidence}))
        applied = None
        if decision.proposal_id is not None:
            applied = scenario != 'actuator_failure'
            controller.acknowledge(decision.proposal_id, applied, start + 10)
        records.append(dict(start=start, scenario=scenario, evidence_revision=revision,
                            before=before, decision=asdict(decision), applied=applied,
                            after=controller.rate, revision=controller.revision))
    return records


if __name__ == '__main__':
    for record in demonstrate():
        print(json.dumps(record, sort_keys=True))
